80	// records. It rejects empty dataset names and datasets declared more than
81	// once; every surviving upstream list is sorted and deduplicated. It does not
82	// check that upstreams resolve to a declared dataset; use
83	// validateAdjacencyReferences for that.
84	func normalizeDatasets(datasets []GraphDataset) (adjacency, error) {
85		adj := make(adjacency, len(datasets))
86		for _, ds := range datasets {
87			if ds.Name == "" {
88				return nil, fmt.Errorf("%w: graph contains a dataset with an empty name", ErrInvalidArgument)
89			}
90			if _, exists := adj[ds.Name]; exists {
91				return nil, fmt.Errorf("%w: dataset %q is declared more than once in the graph", ErrInvalidArgument, ds.Name)
92			}
93			adj[ds.Name] = uniqueSorted(ds.Upstreams)
94		}
95		return adj, nil
96	}
