136	// validateAcyclic reports an error if the parent adjacency contains a cycle
137	// (including a dataset that depends on itself). The error message names the
138	// datasets involved.
139	func validateAcyclic(adj adjacency) error {
140		const (
141			white = 0
142			gray  = 1
143			black = 2
144		)
145		color := make(map[string]int, len(adj))
146		var stack []string
147	
148		var dfs func(node string) error
149		dfs = func(node string) error {
150			color[node] = gray
151			stack = append(stack, node)
152			for _, parent := range adj[node] {
153				switch color[parent] {
154				case gray:
155					// parent is an ancestor of node in the current DFS path, so
156					// following parent edges from parent leads back to parent.
157					idx := 0
158					for stack[idx] != parent {
159						idx++
160					}
161					cycle := make([]string, 0, len(stack)-idx+1)
162					cycle = append(cycle, stack[idx:]...)
163					cycle = append(cycle, parent)
164					return fmt.Errorf("%w: dependency cycle %s", ErrCycle, strings.Join(cycle, " -> "))
165				case white:
166					if err := dfs(parent); err != nil {
167						return err
168					}
169				}
170			}
171			color[node] = black
172			stack = stack[:len(stack)-1]
173			return nil
174		}
175	
176		// Iterate over a sorted snapshot so the first reported cycle is stable
177		// across runs regardless of map iteration order.
178		names := make([]string, 0, len(adj))
179		for name := range adj {
180			names = append(names, name)
181		}
182		sort.Strings(names)
183		for _, name := range names {
184			if color[name] == white {
185				if err := dfs(name); err != nil {
186					return err
187				}
188			}
